import React, { useState } from "react";

const BannerForm = () => {
  const [formData, setFormData] = useState({
    name: "",
    course: "",
    class: "",
    mobile: "",
    email: "",
  });

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };
  //otp ka funtion
  const handleVerifyOTP = () => {
    console.log("OTP Verified");
  };
  //function check krne ke liye sb bhara hai ya nhi
  const handleSubmit = (event) => {
    event.preventDefault();
    let hasEmptyField = false;
    for (const field in formData) {
      if (formData[field] === "") {
        hasEmptyField = true;
        break;
      }
    }

    if (hasEmptyField) {
      alert("Please fill in all fields.");
      return;
    } else {
      alert("form");
    }
    console.log("Form submitted:", formData);
  };
  //contengt on left
  return (
    <div className="w-full min-h-full flex flex-col lg:flex-row items-center justify-between space-x-2 p-4" style={{
      backgroundImage: `url('https://cdn.wallpapersafari.com/79/20/zVpafX.jpg')`,
      backgroundPosition: 'center center',
      backgroundRepeat: 'no-repeat',
      backgroundSize:'cover',
    }}>


    </div>
  );
};

export default BannerForm;
